package com.ecole.gestion_scolaire.transport.controller;
import com.ecole.gestion_scolaire.transport.service.TransportService; import com.ecole.gestion_scolaire.transport.dto.TransportDtos.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import java.time.*;
@RestController @RequestMapping("/api/transport") public class TransportController { private final TransportService s; public TransportController(TransportService s){this.s=s;}
 @GetMapping("/vehicles") @PreAuthorize("hasAuthority('VEHICULE_CONSULTER') or hasAuthority('TRANSPORT_GERER')") Object vehicles(){return s.vehicles();} @PostMapping("/vehicles") @PreAuthorize("hasAuthority('VEHICULE_GERER')") Object cv(@Valid @RequestBody VehicleRequest r){return s.saveVehicle(null,r);} @PutMapping("/vehicles/{id}") @PreAuthorize("hasAuthority('VEHICULE_GERER')") Object uv(@PathVariable Long id,@Valid @RequestBody VehicleRequest r){return s.saveVehicle(id,r);}
 @GetMapping("/drivers") @PreAuthorize("hasAuthority('CHAUFFEUR_CONSULTER') or hasAuthority('TRANSPORT_GERER')") Object drivers(){return s.drivers();} @PostMapping("/drivers") @PreAuthorize("hasAuthority('CHAUFFEUR_GERER')") Object cd(@Valid @RequestBody DriverRequest r){return s.saveDriver(null,r);} @PutMapping("/drivers/{id}") @PreAuthorize("hasAuthority('CHAUFFEUR_GERER')") Object ud(@PathVariable Long id,@Valid @RequestBody DriverRequest r){return s.saveDriver(id,r);}
 @GetMapping("/routes") @PreAuthorize("hasAuthority('CIRCUIT_CONSULTER') or hasAuthority('TRANSPORT_GERER')") Object routes(@RequestParam(required=false) Long schoolYearId){return s.routes(schoolYearId);} @PostMapping("/routes") @PreAuthorize("hasAuthority('CIRCUIT_GERER')") Object cr(@Valid @RequestBody RouteRequest r){return s.saveRoute(null,r);} @PutMapping("/routes/{id}") @PreAuthorize("hasAuthority('CIRCUIT_GERER')") Object ur(@PathVariable Long id,@Valid @RequestBody RouteRequest r){return s.saveRoute(id,r);}
 @GetMapping("/routes/{id}/stops") @PreAuthorize("hasAuthority('CIRCUIT_CONSULTER')") Object stops(@PathVariable Long id){return s.stops(id);} @PostMapping("/routes/{id}/stops") @PreAuthorize("hasAuthority('CIRCUIT_GERER')") Object cs(@PathVariable Long id,@Valid @RequestBody StopRequest r){return s.saveStop(id,null,r);} @PutMapping("/routes/{routeId}/stops/{id}") @PreAuthorize("hasAuthority('CIRCUIT_GERER')") Object us(@PathVariable Long routeId,@PathVariable Long id,@Valid @RequestBody StopRequest r){return s.saveStop(routeId,id,r);}
 @GetMapping("/assignments") @PreAuthorize("hasAuthority('TRANSPORT_ELEVE_CONSULTER')") Object as(@RequestParam(required=false) Long enrollmentId){return s.assignments(enrollmentId);} @PostMapping("/assignments") @PreAuthorize("hasAuthority('TRANSPORT_ELEVE_AFFECTER')") Object ca(@Valid @RequestBody AssignmentRequest r){return s.assign(r);} @PostMapping("/assignments/{id}/close") @PreAuthorize("hasAuthority('TRANSPORT_ELEVE_AFFECTER')") Object close(@PathVariable Long id,@RequestParam(required=false) LocalDate endDate){return s.close(id,endDate);} @PostMapping("/assignments/{id}/generate-charges") @PreAuthorize("hasAuthority('TRANSPORT_ELEVE_AFFECTER') or hasAuthority('PAIEMENT_CONSULTER')") Object gen(@PathVariable Long id){return java.util.Map.of("created",s.generateCharges(id));}
}
